/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK openSaveMenu(s32);                         /* extern */
extern s8 gMenuStateIndex;
extern s32 gBorderSkipActive;
extern s8 gMenuUseTextList;
extern s8 gPendingMenuCommand;
extern s32 gBonusEndDelayFrames;

/* Queues the save menu: clears the bonus-end delay if border skip is active, then opens the save menu. */ void requestSaveMenu(s32 menuArg) {
    if (gBorderSkipActive != 0) {
        gBonusEndDelayFrames = 0;
    }
    gMenuUseTextList = 1;
    gMenuStateIndex = 0xB;
    gPendingMenuCommand = 1;
    openSaveMenu(menuArg & 0xFF);
}
